<script type="module">
import * as THREE from 'three';

/* ── palette (Hokusai print colours) ─────────────────────────── */
const PAL = {
  skyTop:      new THREE.Color(0xd4c5a0),
  skyHorizon:  new THREE.Color(0x8ba0b5),
  prussian:    new THREE.Color(0x1a4a7a),
  indigo:      new THREE.Color(0x0d2b54),
  navy:        new THREE.Color(0x091e3a),
  lightBlue:   new THREE.Color(0x6baed6),
  foam:        new THREE.Color(0xf5f0e8),
  snow:        new THREE.Color(0xffffff),
  boat:        new THREE.Color(0xc4956a),
  boatDark:    new THREE.Color(0x6b4226),
  mountain:    new THREE.Color(0x5a7a99),
  mountainSnow:new THREE.Color(0xe8e4dc),
  horizon:     new THREE.Color(0x7a8fa5),
  foamDot:     new THREE.Color(0xffffff),
};

/* ── renderer / scene / camera ───────────────────────────────── */
const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setSize(window.innerWidth,window.innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();

/* gradient sky */
const skyGeo = new THREE.PlaneGeometry(80,50);
const skyMat = new THREE.ShaderMaterial({
  uniforms:{
    top:{value:PAL.skyTop},
    bottom:{value:PAL.skyHorizon},
  },
  vertexShader:`varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,
  fragmentShader:`uniform vec3 top;uniform vec3 bottom;varying vec2 vUv;void main(){gl_FragColor=vec4(mix(bottom,top,vUv.y),1.);}`,
  side:THREE.DoubleSide,depthWrite:false,
});
const sky = new THREE.Mesh(skyGeo,skyMat);
sky.position.set(0,10,-20);
scene.add(sky);

/* ── helpers ───────────────────────────────────────────────────── */
function waveMaterial(color,opacity=1){
  return new THREE.MeshStandardMaterial({
    color,flatShading:true,transparent:opacity<1,opacity,
    roughness:.7,metalness:0,side:THREE.DoubleSide,
  });
}

/* ── Mount Fuji ────────────────────────────────────────────────── */
function makeFuji(){
  const g = new THREE.ConeGeometry(5,4.5,8);
  const m = new THREE.MeshStandardMaterial({color:PAL.mountain,flatShading:true,roughness:.9});
  const cone = new THREE.Mesh(g,m);
  cone.position.set(4.5,0,-14);
  // snow cap
  const sg = new THREE.ConeGeometry(1.6,1.8,8);
  const sm = new THREE.MeshStandardMaterial({color:PAL.mountainSnow,flatShading:true,roughness:.8});
  const snow = new THREE.Mesh(sg,sm);
  snow.position.set(4.5,2.8,-14);
  scene.add(cone,snow);
}
makeFuji();

/* ── Wave function ─────────────────────────────────────────────── */
// Hokusai's wave: tall on left, curling over, with secondary waves
function waveZ(x,z){
  // main wave peak (left side)
  const main = Math.exp(-Math.pow((x+2.5)/2.2,2))*Math.pow(Math.max(0,Math.sin(z*0.6+1.2)),0.7)*8;
  // foreground swell
  const fg = Math.sin(z*0.8-0.5)*1.8*Math.exp(-Math.pow((x-1)/5,2));
  // right swell
  const rg = Math.sin(z*0.5+0.3)*1.2*Math.exp(-Math.pow((x-3)/4,2));
  return main+fg+rg;
}

